using Autodesk.AutoCAD.Runtime;using System.Windows.Forms;using AcApp=Autodesk.AutoCAD.ApplicationServices.Application;
[assembly:ExtensionApplication(typeof(LSE.AutoCADElectrical.WireToFrom.Plugin))][assembly:CommandClass(typeof(LSE.AutoCADElectrical.WireToFrom.Commands))]
namespace LSE.AutoCADElectrical.WireToFrom;
public sealed class Plugin:IExtensionApplication{public void Initialize(){}public void Terminate(){}}
public sealed class Commands{
 [CommandMethod("LSETOFROM",CommandFlags.Modal)]public void Run(){try{var s=SettingsService.Load();string active=AcadeInterop.TryGetActiveProject(s);string start=active.Length>0?active:AcadeInterop.GuessProjectNearActiveDrawing();string scratch=AcadeInterop.TryGetScratchDbPath(s);string refresh=string.IsNullOrWhiteSpace(s.RefreshDbLisp)?"":AcadeInterop.RefreshDatabase(s);
   using var f=new ToFromForm(start,active,scratch,AcadeInterop.CurrentDrawingPath(),refresh);AcApp.ShowModalDialog(f);}catch(System.Exception ex){ErrorService.Show(null,"LSETOFROM",ex);}}
 [CommandMethod("LSETOFROMEXPORT",CommandFlags.Modal)]public void ExportOnly(){try{var (s,c,p,scratch)=Prepare();var issues=new List<Issue>();var notes=new List<string>();var rows=DataSourceService.Load(s,c,p,scratch,null,issues,notes,out string src);
   var plan=IdentifierService.Plan(p,rows,c,s,AcadeInterop.Bridge(c),false,null);plan.DataSource=src;plan.Issues.InsertRange(0,issues);plan.Log.InsertRange(1,notes);var res=RunService.Execute(plan,s,AcadeInterop.Bridge(c),true);
   using var f=new TextReportForm("LSE_ToFrom export: "+p.Name,res.Report+Environment.NewLine+Environment.NewLine+Export.Validation(plan,res));AcApp.ShowModalDialog(f);}catch(System.Exception ex){ErrorService.Show(null,"LSETOFROMEXPORT",ex);}}
 [CommandMethod("LSETOFROMVALIDATE",CommandFlags.Modal)]public void ValidateOnly(){try{var (s,c,p,scratch)=Prepare();var issues=new List<Issue>();var notes=new List<string>();var rows=DataSourceService.Load(s,c,p,scratch,null,issues,notes,out string src);
   var plan=IdentifierService.Plan(p,rows,c,s,AcadeInterop.Bridge(c),true,s.CurrentDrawingOnly?AcadeInterop.CurrentDrawingPath():null);plan.DataSource=src;plan.Issues.InsertRange(0,issues);plan.Log.InsertRange(1,notes);
   string path=Export.WriteValidation(plan,null,ProjectService.OutputFile(p,c.Csv,c.Csv.ValidationFile));using var f=new TextReportForm("LSE_ToFrom validation: "+p.Name,Export.Validation(plan,null)+Environment.NewLine+Environment.NewLine+"Saved to "+path+Environment.NewLine+Environment.NewLine+IdentifierService.Render(plan));AcApp.ShowModalDialog(f);}catch(System.Exception ex){ErrorService.Show(null,"LSETOFROMVALIDATE",ex);}}
 [CommandMethod("LSETOFROMDISCOVER",CommandFlags.Modal)]public void Discover(){try{var (s,c,p,scratch)=Prepare();var searched=new List<string>();string path=ProjectService.DatabasePath(p,c.Database,scratch,searched);var x=new List<string>{"LSE_ToFrom discovery  "+DateTime.Now.ToString("s")+"  build "+BuildInfo.Release,"Project: "+p.WdpPath+$"  ({p.Drawings.Count} drawing(s))","LISP bridge:"};x.AddRange(AcadeInterop.ProbeBridge(s));
   x.AddRange(new[]{"Database path used: "+path+(File.Exists(path)?$"  (written {File.GetLastWriteTime(path):yyyy-MM-dd HH:mm})":"  MISSING"),"Paths looked at: "+string.Join("; ",searched),"Config: "+c.Source,"Current wireSql: "+(c.Database.WireSql.Length>0?c.Database.WireSql:"(empty)"),""});
   if(!File.Exists(path)){x.Add("The project database was not found. Make this project active, run a native report (Reports > Schematic > Wire From/To) so AutoCAD Electrical creates it, and run LSETOFROMDISCOVER again. If it is still missing, look at what the scratch database LISP returned above: add that folder to database.searchFolders in the config, or set database.pathPattern to the full path.");Finish(p,x);return;}
   var schema=ScratchDb.Schema(path,c.Database);x.Add(ScratchDb.Describe(schema,c.Database));var best=schema.Where(t=>t.Score>=3).OrderByDescending(t=>t.Score).ToList();
   if(best.Count>0){string sql=ScratchDb.SuggestSql(best[0]);x.Add("");x.Add("Suggested database.wireSql: "+sql);var sample=ScratchDb.Query(path,sql,c.Database.Providers,5);x.Add("First rows:");foreach(var r in sample)x.Add("  "+string.Join(" | ",r.Select(k=>k.Key+"="+(k.Value=="\u0000"?"":k.Value))));
    if(!c.Database.WireSql.Trim().Equals(sql,StringComparison.OrdinalIgnoreCase)&&MessageBox.Show("Table "+best[0].Name+" carries "+best[0].Score+" of the "+c.Database.CandidateColumns.Count+" from/to columns.\n\nWrite\n  "+sql+"\ninto database.wireSql of\n  "+c.Source+"\nand mark the confidence 'discovered'?","LSE_ToFrom discovery",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes){c.Database.WireSql=sql;c.Database.Confidence="discovered "+DateTime.Now.ToString("yyyy-MM-dd");ConfigService.Save(c,s.ConfigPath);x.Add("Config updated: database.wireSql = "+sql);}}
   else x.Add("No table holds three or more of the candidate columns. Compare the column names in the list above with database.candidateColumns and database.columns in the config, then run LSETOFROMDISCOVER again.");
   Finish(p,x);}catch(System.Exception ex){ErrorService.Show(null,"LSETOFROMDISCOVER",ex);}}
 static void Finish(ProjectInfo p,List<string> x){Directory.CreateDirectory(SettingsService.LogFolder);string note=Path.Combine(SettingsService.LogFolder,$"Discovery_{DateTime.Now:yyyyMMdd_HHmmss}.txt");File.WriteAllLines(note,x);x.Add("");x.Add("Findings note saved: "+note);
  using var f=new TextReportForm("LSE_ToFrom discovery: "+p.Name,string.Join(Environment.NewLine,x));AcApp.ShowModalDialog(f);}
 [CommandMethod("LSETOFROMBLOCKS",CommandFlags.Modal)]public void Blocks(){try{var s=SettingsService.Load();var c=ConfigService.Load(s.ConfigPath);var log=new List<string>();
   using(var d=new FolderBrowserDialog{Description="Folder for "+c.Schematic.BlockH+".dwg and "+c.Schematic.BlockV+".dwg (the DLL folder or schematic.blockFolder in the config)",SelectedPath=RunService.LibraryPaths(c)[0]}){if(d.ShowDialog()==DialogResult.OK)log.AddRange(LabelWriter.ExportBlocks(d.SelectedPath,c.Schematic));else log.Add("Block export skipped.");}
   var doc=AcApp.DocumentManager.MdiActiveDocument;if(doc is not null&&MessageBox.Show("Also add layer "+c.Schematic.LabelLayer+" and the two label blocks to the current drawing ("+Path.GetFileName(doc.Name)+")?\n\nDo this once in the department template (.dwt) and save it.","LSE_ToFrom blocks",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes)log.AddRange(LabelWriter.AddToDrawing(doc,c.Schematic,RunService.LibraryPaths(c)));
   using var f=new TextReportForm("LSE_ToFrom blocks",string.Join(Environment.NewLine,log));AcApp.ShowModalDialog(f);}catch(System.Exception ex){ErrorService.Show(null,"LSETOFROMBLOCKS",ex);}}
 [CommandMethod("LSETOFROMSETTINGS",CommandFlags.Modal)]public void Settings(){try{using var f=new ToFromSettingsForm();AcApp.ShowModalDialog(f);}catch(System.Exception ex){ErrorService.Show(null,"LSETOFROMSETTINGS",ex);}}
 [CommandMethod("LSETOFROMDIAG",CommandFlags.Modal)]public void Diag(){try{List<string> bridge;try{bridge=AcadeInterop.ProbeBridge(SettingsService.Load());}catch(System.Exception ex){bridge=new List<string>{"  probe failed: "+ex.Message};}
   using var f=new TextReportForm("LSE_ToFrom Diagnostics",DiagnosticsService.BuildReport(bridge));AcApp.ShowModalDialog(f);}catch(System.Exception ex){ErrorService.Show(null,"LSETOFROMDIAG",ex);}}
 static (AppSettings,ToFromConfig,ProjectInfo,string) Prepare(){var s=SettingsService.Load();var c=ConfigService.Load(s.ConfigPath);string wdp=AcadeInterop.TryGetActiveProject(s);if(wdp.Length==0)wdp=AcadeInterop.GuessProjectNearActiveDrawing();
  if(wdp.Length==0)throw new InvalidOperationException("No active AutoCAD Electrical project was detected and no single .wdp sits next to the current drawing. Activate the project in the Project Manager, or use LSETOFROM and browse to the .wdp.");
  string refresh=string.IsNullOrWhiteSpace(s.RefreshDbLisp)?"":AcadeInterop.RefreshDatabase(s);string scratch=AcadeInterop.TryGetScratchDbPath(s);var p=ProjectService.Read(wdp);return (s,c,p,scratch);}
}
